import React, { useMemo, useState, useEffect } from "react";
import Papa from "papaparse";
import { motion, AnimatePresence } from "framer-motion";
import { Search, Filter, Upload, ChevronDown, ChevronUp, Download } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";

/**
 * Jira-style Swimlane Dashboard
 * - Reads a CSV exported from Jira (like the one you attached)
 * - Groups issues by: Custom field (Owner - AUTOI)
 * - Shows swimlanes resembling the Active Sprint board
 * - Fully static (client-side). No backend required.
 *
 * How to use:
 * 1) Click "Upload CSV" and select your Jira export.
 * 2) Optionally filter by Status, search by text, or collapse lanes.
 * 3) Hover tooltips show full summary text; click Issue Key to open Jira (if your CSV has fully-qualified URLs, otherwise it copies the key).
 */

// --- Helpers & Types ---
const STATUS_ORDER = ["Delay", "To Do", "In Progress", "Done"]; // ordering in each lane

const STATUS_COLOR_CLASS: Record<string, string> = {
  "Delay": "bg-amber-200 text-amber-900 border-amber-300",
  "To Do": "bg-slate-100 text-slate-900 border-slate-200",
  "In Progress": "bg-blue-100 text-blue-900 border-blue-200",
  "Done": "bg-emerald-100 text-emerald-900 border-emerald-200",
};

const STATUS_PILL_CLASS: Record<string, string> = {
  "Delay": "bg-amber-600 text-white",
  "To Do": "bg-slate-600 text-white",
  "In Progress": "bg-blue-600 text-white",
  "Done": "bg-emerald-600 text-white",
};

function classNames(...xs: Array<string | false | null | undefined>) {
  return xs.filter(Boolean).join(" ");
}

// --- Component ---
export default function Component() {
  const [rawRows, setRawRows] = useState<any[]>([]);
  const [query, setQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState<string[]>([]); // empty = all
  const [collapsed, setCollapsed] = useState<Record<string, boolean>>({});

  // Try to auto-load a CSV named exactly like the one you uploaded (optional nicety)
  useEffect(() => {
    const tryAutoLoad = async () => {
      try {
        const res = await fetch("/mnt/data/All items in the current sprint (One Firm Jira).csv");
        if (res.ok) {
          const text = await res.text();
          Papa.parse(text, {
            header: true,
            skipEmptyLines: true,
            complete: (res) => setRawRows(res.data as any[]),
          });
        }
      } catch (e) {
        // Ignore if not available in this environment
      }
    };
    tryAutoLoad();
  }, []);

  const owners = useMemo(() => {
    const set = new Set<string>();
    rawRows.forEach((r) => set.add(r["Custom field (Owner - AUTOI)"] || "Unassigned"));
    return Array.from(set).sort((a, b) => a.localeCompare(b));
  }, [rawRows]);

  const filteredRows = useMemo(() => {
    const q = query.trim().toLowerCase();
    return rawRows.filter((r) => {
      const owner = r["Custom field (Owner - AUTOI)"] || "Unassigned";
      const status = r["Status"] || "To Do";
      const hay = `${r["Issue key"]} ${r["Summary"]} ${owner}`.toLowerCase();
      const matchesQ = q ? hay.includes(q) : true;
      const matchesStatus = statusFilter.length ? statusFilter.includes(status) : true;
      return matchesQ && matchesStatus;
    });
  }, [rawRows, query, statusFilter]);

  const grouped = useMemo(() => {
    const map: Record<string, any[]> = {};
    filteredRows.forEach((r) => {
      const owner = r["Custom field (Owner - AUTOI)"] || "Unassigned";
      if (!map[owner]) map[owner] = [];
      map[owner].push(r);
    });
    return map;
  }, [filteredRows]);

  const metrics = useMemo(() => {
    const total = filteredRows.length;
    const byStatus: Record<string, number> = {};
    STATUS_ORDER.forEach((s) => (byStatus[s] = 0));
    filteredRows.forEach((r) => {
      const s = r["Status"] || "To Do";
      byStatus[s] = (byStatus[s] || 0) + 1;
    });
    const done = byStatus["Done"] || 0;
    const progressPct = total ? Math.round((done / total) * 100) : 0;
    return { total, byStatus, progressPct };
  }, [filteredRows]);

  // --- UI ---
  return (
    <div className="min-h-screen bg-gradient-to-b from-white to-slate-50">
      {/* Top bar */}
      <div className="sticky top-0 z-30 backdrop-blur bg-white/70 border-b border-slate-200">
        <div className="max-w-7xl mx-auto px-4 py-3 flex items-center gap-3">
          <h1 className="text-2xl font-bold tracking-tight">Active Sprint – Owner Swimlanes</h1>
          <span className="text-xs text-slate-500">Grouped by “Custom field (Owner - AUTOI)”</span>
          <div className="ml-auto flex items-center gap-2">
            <CSVUpload onRows={setRawRows} />
          </div>
        </div>
      </div>

      {/* Controls & Metrics */}
      <div className="max-w-7xl mx-auto px-4 py-4 grid md:grid-cols-3 gap-4">
        <Card className="col-span-2">
          <CardContent className="p-4 flex flex-wrap items-center gap-3">
            <div className="relative flex-1 min-w-[220px]">
              <Search className="absolute left-2 top-2.5 h-4 w-4 text-slate-400" />
              <input
                className="w-full rounded-xl border border-slate-200 bg-white px-8 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-200"
                placeholder="Search by key, summary, or owner…"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
              />
            </div>

            <StatusMultiSelect selected={statusFilter} onChange={setStatusFilter} />

            <Button
              variant="secondary"
              onClick={() => setCollapsed((c) => {
                const allCollapsed: Record<string, boolean> = {};
                owners.forEach((o) => (allCollapsed[o] = true));
                return allCollapsed;
              })}
            >Collapse all</Button>
            <Button
              variant="secondary"
              onClick={() => setCollapsed((c) => {
                const allOpen: Record<string, boolean> = {};
                owners.forEach((o) => (allOpen[o] = false));
                return allOpen;
              })}
            >Expand all</Button>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <div className="text-xs uppercase tracking-wide text-slate-500">Sprint Progress</div>
                <div className="text-2xl font-semibold">{metrics.progressPct}%</div>
              </div>
              <div className="text-sm text-slate-500">{metrics.total} issues</div>
            </div>
            <div className="mt-3 h-2 w-full bg-slate-100 rounded-full overflow-hidden">
              <div
                className="h-full bg-emerald-500"
                style={{ width: `${metrics.progressPct}%` }}
              />
            </div>
            <div className="mt-3 flex flex-wrap gap-2">
              {STATUS_ORDER.map((s) => (
                <span key={s} className={classNames("px-2 py-0.5 rounded-full text-xs", STATUS_PILL_CLASS[s])}>
                  {s}: {metrics.byStatus[s] || 0}
                </span>
              ))}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Swimlanes */}
      <div className="max-w-7xl mx-auto px-4 pb-10 space-y-4">
        {owners.map((owner) => (
          <Lane
            key={owner}
            owner={owner}
            rows={(grouped[owner] || [])}
            collapsed={!!collapsed[owner]}
            onToggle={() => setCollapsed((c) => ({ ...c, [owner]: !c[owner] }))}
          />
        ))}

        {owners.length === 0 && (
          <div className="text-center text-slate-500 py-20">
            <p className="mb-3">Upload your Jira CSV to see swimlanes.</p>
            <p className="text-xs">Required columns: <code>Issue key</code>, <code>Summary</code>, <code>Status</code>, <code>Custom field (Owner - AUTOI)</code>.</p>
          </div>
        )}
      </div>
    </div>
  );
}

// --- Components ---
function CSVUpload({ onRows }: { onRows: (rows: any[]) => void }) {
  const onChange = (file?: File) => {
    if (!file) return;
    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (res) => {
        onRows(res.data as any[]);
      },
    });
  };

  return (
    <label className="inline-flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm cursor-pointer hover:shadow-sm">
      <Upload className="h-4 w-4" />
      Upload CSV
      <input
        type="file"
        accept=".csv"
        className="hidden"
        onChange={(e) => onChange(e.target.files?.[0])}
      />
    </label>
  );
}

function StatusMultiSelect({ selected, onChange }: { selected: string[]; onChange: (s: string[]) => void }) {
  const all = STATUS_ORDER;
  const isSelected = (s: string) => selected.includes(s);
  const toggle = (s: string) => {
    if (isSelected(s)) onChange(selected.filter((x) => x !== s));
    else onChange([...selected, s]);
  };

  return (
    <div className="flex items-center gap-2 flex-wrap">
      <span className="text-xs text-slate-500 flex items-center gap-1"><Filter className="h-4 w-4"/>Status:</span>
      {all.map((s) => (
        <button
          key={s}
          onClick={() => toggle(s)}
          className={classNames(
            "px-2 py-1 rounded-full text-xs border",
            isSelected(s)
              ? STATUS_PILL_CLASS[s]
              : "bg-white text-slate-700 border-slate-200 hover:bg-slate-50"
          )}
        >
          {s}
        </button>
      ))}
      {selected.length > 0 && (
        <button
          onClick={() => onChange([])}
          className="text-xs text-slate-500 underline underline-offset-2"
        >
          Clear
        </button>
      )}
    </div>
  );
}

function Lane({ owner, rows, collapsed, onToggle }: { owner: string; rows: any[]; collapsed: boolean; onToggle: () => void }) {
  const counts = useMemo(() => {
    const c: Record<string, number> = {};
    STATUS_ORDER.forEach((s) => (c[s] = 0));
    rows.forEach((r) => (c[r["Status"] || "To Do"] += 1));
    const total = rows.length;
    return { c, total };
  }, [rows]);

  // Sort within a lane: by STATUS_ORDER, then by Issue key number desc
  const sorted = useMemo(() => {
    const clone = [...rows];
    clone.sort((a, b) => {
      const sa = STATUS_ORDER.indexOf(a["Status"]) ?? 99;
      const sb = STATUS_ORDER.indexOf(b["Status"]) ?? 99;
      if (sa !== sb) return sa - sb;
      const na = parseInt(String(a["Issue key"]).split("-")[1] || "0", 10);
      const nb = parseInt(String(b["Issue key"]).split("-")[1] || "0", 10);
      return nb - na;
    });
    return clone;
  }, [rows]);

  return (
    <div className="rounded-2xl border border-slate-200 bg-white shadow-sm">
      <button
        onClick={onToggle}
        className="w-full flex items-center justify-between px-4 py-3 hover:bg-slate-50"
      >
        <div className="flex items-center gap-3">
          <div className="text-lg font-semibold">{owner}</div>
          <div className="flex gap-1">
            {STATUS_ORDER.map((s) => (
              <span key={s} className={classNames("px-2 py-0.5 rounded-full text-xs", STATUS_PILL_CLASS[s])}>
                {s}: {counts.c[s]}
              </span>
            ))}
          </div>
        </div>
        <div className="text-slate-500 flex items-center gap-2">
          <span className="text-xs">{counts.total} issues</span>
          {collapsed ? <ChevronDown className="h-4 w-4"/> : <ChevronUp className="h-4 w-4"/>}
        </div>
      </button>

      <AnimatePresence initial={false}>
        {!collapsed && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.2 }}
            className="px-4 pb-4"
          >
            {/* Columns per status to mimic Jira swimlanes */}
            <div className="grid md:grid-cols-4 gap-3">
              {STATUS_ORDER.map((status) => (
                <div key={status} className="rounded-xl border border-slate-100 bg-slate-50/50">
                  <div className="px-3 py-2 text-xs font-semibold text-slate-600 border-b border-slate-100">
                    {status}
                  </div>
                  <div className="p-3 space-y-2 max-h-[380px] overflow-auto">
                    {sorted.filter((r) => (r["Status"] || "To Do") === status).map((r) => (
                      <IssueCard key={r["Issue id"] || r["Issue key"]} row={r} />
                    ))}
                    {sorted.filter((r) => (r["Status"] || "To Do") === status).length === 0 && (
                      <div className="text-xs text-slate-400 italic">No items</div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

function IssueCard({ row }: { row: any }) {
  const key = row["Issue key"];
  const summary = row["Summary"];
  const status = row["Status"] || "To Do";
  const owner = row["Custom field (Owner - AUTOI)"] || "Unassigned";
  const parent = row["Parent key"] || row["Parent"] || "";
  const type = row["Issue Type"];

  return (
    <div className={classNames("rounded-lg border text-sm p-3 shadow-xs hover:shadow transition", STATUS_COLOR_CLASS[status] || "bg-white border-slate-200")}>
      <div className="flex items-center justify-between gap-2">
        <a
          className="font-semibold underline decoration-dotted underline-offset-2"
          href={`#${key}`}
          title="Click to copy key"
          onClick={(e) => {
            e.preventDefault();
            navigator.clipboard.writeText(key);
          }}
        >{key}</a>
        <span className={classNames("px-2 py-0.5 rounded-full text-[10px] uppercase tracking-wide", STATUS_PILL_CLASS[status])}>{type || status}</span>
      </div>
      <div className="mt-1 line-clamp-3" title={summary}>{summary}</div>
      <div className="mt-2 flex items-center justify-between text-xs text-slate-600">
        <span title="Owner">👤 {owner}</span>
        {parent && <span className="text-slate-500" title="Parent">📦 {parent}</span>}
      </div>
    </div>
  );
}